  const root=document.querySelector('#alphabet-explorer'), input=document.querySelector('#resource-search-input'), form=document.querySelector('#resource-search-form');
  if(!root||!input||!form)return;
  const letters=[...root.querySelectorAll('.alphabet-explorer__letter')],panel=root.querySelector('#alphabet-explorer-panel'),title=root.querySelector('#alphabet-explorer-panel-title'),terms=root.querySelector('#alphabet-explorer-terms'),close=root.querySelector('#alphabet-explorer-close'),status=root.querySelector('#alphabet-explorer-status'),more=root.querySelector('#alphabet-explorer-more');
  let active=null,closeTimer=null,expanded=false,current=[]; const LIMIT=14; const coarse=()=>matchMedia('(hover: none),(pointer: coarse)').matches;
  const priority=item=>{const src=item.sources||[], n=(item.resources||[]).length;if(src.includes('usage'))return 0;if(src.includes('notion')&&n>0&&n<=8)return 1;if(src.includes('notion')&&n<=15)return 2;if(src.includes('referentiel')&&n<=8)return 3;return 4;};
  function clearTimer(){if(closeTimer){clearTimeout(closeTimer);closeTimer=null}}
  function setExpanded(btn,on){btn?.setAttribute('aria-expanded',on?'true':'false')}
  function closePanel(focus=false){clearTimer();if(active){setExpanded(active,false);if(focus)active.focus()}active=null;panel.hidden=true;terms.innerHTML='';status.textContent='';more.hidden=true;expanded=false}
  function launch(item){if(item.resources?.length){document.dispatchEvent(new CustomEvent('gpme:search-ids',{detail:{ids:item.resources,label:item.label}}));}else{input.value=item.query||item.label;input.dispatchEvent(new Event('input',{bubbles:true}));form.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));}status.textContent=`Recherche lancée : ${item.label}`;document.querySelector('#results-title')?.scrollIntoView({behavior:'smooth',block:'start'})}
  function ordered(items){return [...items].sort((a,b)=>priority(a)-priority(b)||a.label.localeCompare(b.label,'fr'))}
  function render(){terms.innerHTML='';const shown=expanded?current:current.slice(0,LIMIT);shown.forEach(item=>{const row=document.createElement('div');row.className='alphabet-explorer__item';const b=document.createElement('button');b.type='button';b.className='alphabet-explorer__term';b.textContent=item.label;b.addEventListener('click',()=>launch(item));row.appendChild(b);terms.appendChild(row)});more.hidden=current.length<=LIMIT;more.textContent=expanded?'Réduire la liste':`Voir tous les termes (${current.length})`;status.textContent=expanded?`${current.length} termes affichés.`:`${Math.min(LIMIT,current.length)} repères principaux sur ${current.length} termes.`}
  function openLetter(btn){const l=btn.dataset.letter,items=ordered(DATA[l]||[]);if(!items.length)return;clearTimer();if(active&&active!==btn)setExpanded(active,false);active=btn;setExpanded(btn,true);title.textContent=`Termes en ${l}`;current=items;expanded=false;render();panel.hidden=false}
  more.addEventListener('click',()=>{expanded=!expanded;render()});close.addEventListener('click',()=>closePanel(true));
  letters.forEach((btn,i)=>{const has=(DATA[btn.dataset.letter]||[]).length>0;if(!has){btn.setAttribute('aria-disabled','true');btn.tabIndex=-1;return}btn.addEventListener('mouseenter',()=>{if(!coarse())openLetter(btn)});btn.addEventListener('focus',()=>openLetter(btn));btn.addEventListener('click',()=>{if(active===btn&&!panel.hidden&&coarse())closePanel();else openLetter(btn)});btn.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();closePanel(true)}else if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();const d=e.key==='ArrowRight'?1:-1;let n=i;for(let k=0;k<letters.length;k++){n=(n+d+letters.length)%letters.length;if(letters[n].getAttribute('aria-disabled')!=='true'){letters[n].focus();break}}}else if(e.key==='ArrowDown'&&!panel.hidden){e.preventDefault();terms.querySelector('button')?.focus()}})});
  root.addEventListener('mouseenter',clearTimer);root.addEventListener('mouseleave',()=>{if(!coarse())closeTimer=setTimeout(()=>closePanel(false),250)});panel.addEventListener('mouseenter',clearTimer);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden)closePanel(true)});
